/* Shared local demonstration records for the club, client area and operations. */
const OPS_DAY='2026-11-08';
const opId=p=>p+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();
const opDate=d=>new Date(String(d||OPS_DAY).slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR');
function opAddMonth(date,n=1){const d=new Date(date.slice(0,10)+'T12:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
const opMonth=d=>new Date((d||OPS_DAY).slice(0,7)+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
function seedOps(){
  const names=['Ana Martins','João Santos','Rute Almeida','Samuel Costa','Débora Lima','Lucas Rocha','Ester Souza','Paulo Dias'];
  const clients=names.map((name,i)=>({id:'CLI-'+(1001+i),name,email:name.split(' ')[0].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')+'.clube@exemplo.com',phone:'1199999000'+i,status:'Ativo',city:['São Paulo','Campinas','Curitiba','Belo Horizonte'][i%4],state:['SP','SP','PR','MG'][i%4],street:'Rua Exemplo',number:String(100+i),district:'Centro',cep:'01001-000',created:'2026-0'+(5+i%4)+'-08',notes:'Cadastro fictício para explorar o painel.'}));
  const profiles=['Católica','Evangélica','Cristã'];
  const subs=clients.slice(0,6).map((c,i)=>({id:'ASS-'+(2001+i),customerId:c.id,profile:profiles[i%3],finish:['Marfim','Terracota','Surpresa'][i%3],price:129.9,status:['Ativa','Ativa','Ativa','Pausada','Pagamento pendente','Cancelada'][i],payment:i%3===1?'pix':'card',created:'2026-0'+(7+i%3)+'-08',nextRenewal:'2026-12-08',nextShipment:'2026-11-15',address:{...c},history:[{date:'2026-10-08',label:'Assinatura de demonstração criada.'}]}));
  const orders=[],charges=[],jobs=[];
  clients.forEach((c,i)=>{const club=i<6,s=club?subs[i]:null;const status=['Em produção','Pronto para envio','Enviado','Entregue','Aguardando pagamento','Cancelado','Confirmado','Em acabamento'][i];const ids=club?(i%3===0?['nossa-senhora','cruz-essencial']:i%3===1?['biblia-viva','palavra-fe']:['cruz-essencial','espirito-santo']):[products[i%products.length].id];const items=ids.map(id=>{const p=products.find(x=>x.id===id);return{id,name:p.name,img:p.img,qty:1,price:p.price,color:'Marfim',size:p.sizes[0]}});const total=club?129.9:items.reduce((a,x)=>a+x.price,0)+18.9;const oid='PED-'+(4001+i),chargeid='COB-'+(5001+i);orders.push({id:oid,customerId:c.id,subscriptionId:s?.id||null,type:club?'Clube':'Loja',edition:club?'Novembro · Esperança que renova':null,profile:s?.profile||'',items,total,shipping:club?0:18.9,status,created:'2026-11-0'+(1+i%6),due:'2026-11-'+(12+i),address:{...c},chargeId:chargeid,tracking:['Enviado','Entregue'].includes(status)?'DEMO'+(88001+i):'',carrier:'Correios (simulação)',priority:i===0?'Alta':'Normal',notes:'Pedido fictício de demonstração.'});charges.push({id:chargeid,customerId:c.id,subscriptionId:s?.id||null,orderId:oid,amount:total,method:s?.payment||'card',status:status==='Aguardando pagamento'?'Pendente':status==='Cancelado'?'Cancelada':'Pago',due:'2026-11-08',paidAt:status==='Aguardando pagamento'||status==='Cancelado'?null:'2026-11-0'+(1+i%6),description:club?'Clube · edição de novembro':'Compra avulsa',cycle:'2026-11'});if(['Confirmado','Em produção','Em acabamento'].includes(status))jobs.push({id:'OP-'+(7001+i),orderId:oid,stage:status==='Confirmado'?'Fila':status==='Em produção'?'Impressão':'Acabamento',printer:['Bambu A1 · demo','Bambu P1S · demo','Estação 3 · demo'][i%3],hours:4+i,assignee:['Camila','Pedro','Lia'][i%3],priority:i===0?'Alta':'Normal',due:'2026-11-'+(10+i)});});
  return {schema:1,clients,subscriptions:subs,orders,charges,jobs,expenses:[{id:'DES-1',name:'Filamento PLA · lote de demonstração',amount:460,category:'Produção',date:'2026-11-04',status:'Pago'},{id:'DES-2',name:'Embalagens das cestas',amount:186,category:'Embalagem',date:'2026-11-05',status:'Pago'},{id:'DES-3',name:'Fretes da edição de novembro',amount:246,category:'Frete',date:'2026-11-15',status:'Previsto'}],tickets:[{id:'AT-8001',customerId:clients[1].id,subject:'Alterar endereço da próxima cesta',category:'Assinatura',status:'Aberto',priority:'Normal',assignee:'Camila',created:'2026-11-08',messages:[{by:'cliente',text:'Posso atualizar o endereço antes do próximo envio?',date:'2026-11-08'}]},{id:'AT-8002',customerId:clients[4].id,subject:'Dúvida sobre pagamento mensal',category:'Pagamento',status:'Em atendimento',priority:'Alta',assignee:'Lia',created:'2026-11-07',messages:[{by:'cliente',text:'Gostaria de testar o pagamento pelo Pix.',date:'2026-11-07'},{by:'equipe',text:'Você pode alterar a forma de pagamento na área da assinatura de demonstração.',date:'2026-11-08'}]}],team:[{id:'U1',name:'Camila Oliveira',email:'camila@exemplo.com',role:'Atendimento',status:'Ativo'},{id:'U2',name:'Pedro Almeida',email:'pedro@exemplo.com',role:'Produção',status:'Ativo'},{id:'U3',name:'Lia Costa',email:'lia@exemplo.com',role:'Financeiro',status:'Ativo'}],printers:[{id:'M1',name:'Bambu A1 · demo',status:'Imprimindo',capacity:24},{id:'M2',name:'Bambu P1S · demo',status:'Disponível',capacity:24},{id:'M3',name:'Estação 3 · demo',status:'Manutenção',capacity:16}],productOverrides:{},extraProducts:[],settings:{clubName:'Clube Cesta com Jesus',price:129.9,dispatchDay:15,edition:'Esperança que renova',editionMonth:'2026-11',storeName:'Âmago 3D',email:'atendimento@exemplo.com',phone:'(11) 99999-0000',lowStock:5,profiles:{'Católica':['nossa-senhora','cruz-essencial'],'Evangélica':['biblia-viva','palavra-fe'],'Cristã':['cruz-essencial','espirito-santo']}},inventory:Object.fromEntries(products.map((p,i)=>[p.id,{stock:18+i*3,cost:Math.round(p.price*.35*100)/100,sku:'AMG-'+(101+i)}])),campaigns:[],audit:[{id:'LOG-1',date:'2026-11-08T10:00:00',actor:'Sistema demo',action:'Ambiente de demonstração iniciado',entity:'Operação'}]};
}
let ops=readStore('operations-v1',null)||seedOps();
function saveOps(){persist('operations-v1',ops)}
function auditOps(action,entity,actor='Administrador demo'){ops.audit.unshift({id:opId('LOG'),date:new Date().toISOString(),actor,action,entity});ops.audit=ops.audit.slice(0,150);saveOps()}
function applyProductOps(){for(const p of products){if(ops.productOverrides[p.id])Object.assign(p,ops.productOverrides[p.id])}for(const p of ops.extraProducts||[])if(!products.some(x=>x.id===p.id))products.push(p)}
function opClient(id){return ops.clients.find(x=>x.id===id)}
function opOrder(id){return ops.orders.find(x=>x.id===id)}
function opSubscription(id){return ops.subscriptions.find(x=>x.id===id)}
function opCurrentClient(){return customer?ops.clients.find(c=>c.id===customer.clubCustomerId||c.email.toLowerCase()===customer.email.toLowerCase()):null}
function opCurrentSub(){const c=opCurrentClient();return c?ops.subscriptions.filter(s=>s.customerId===c.id).sort((a,b)=>b.created.localeCompare(a.created))[0]:null}
function opStatus(text){const cls=['Pago','Ativa','Ativo','Entregue','Resolvido','Disponível','Concluída'].includes(text)?'good':['Pendente','Pagamento pendente','Aberto','Aguardando pagamento','Pausada','Previsto'].includes(text)?'warn':['Cancelada','Cancelado','Estornado','Recusado','Inativo','Manutenção'].includes(text)?'bad':'info';return `<span class="op-status ${cls}">${esc(text)}</span>`}
function syncStoreOps(){for(const o of orders){if(ops.orders.some(x=>x.sourceOrderId===o.id))continue;let c=ops.clients.find(x=>x.email===o.address?.email);if(!c){c={id:opId('CLI'),name:o.address?.name||'Cliente de demonstração',email:o.address?.email||'cliente@exemplo.com',status:'Ativo',created:OPS_DAY,city:o.address?.city||'São Paulo',state:o.address?.state||'SP',...o.address};ops.clients.push(c)}const chargeId=opId('COB');const id='LOJA-'+o.number;ops.orders.push({id,sourceOrderId:o.id,customerId:c.id,type:'Loja',items:o.items,total:o.total,shipping:18.9,status:o.status==='Aguardando Pix'?'Aguardando pagamento':'Confirmado',created:OPS_DAY,due:'2026-11-18',address:{...o.address},chargeId,tracking:'',carrier:'Correios (simulação)',priority:'Normal',notes:'Sincronizado do checkout de demonstração.'});ops.charges.push({id:chargeId,customerId:c.id,orderId:id,amount:o.total,method:o.payment,status:o.status==='Aguardando Pix'?'Pendente':'Pago',due:OPS_DAY,paidAt:o.status==='Aguardando Pix'?null:OPS_DAY,description:'Compra na loja',cycle:OPS_DAY.slice(0,7)})}saveOps()}
function setOrderOps(id,status){const o=opOrder(id);if(!o)return;o.status=status;if(status==='Enviado')o.sentAt=OPS_DAY;if(status==='Entregue')o.deliveredAt=OPS_DAY;const original=orders.find(x=>x.id===o.sourceOrderId);if(original){original.status=status;persist('orders',orders)}auditOps('Status do pedido: '+status,id)}
function productionOps(id){const o=opOrder(id);if(!o||ops.jobs.some(j=>j.orderId===id&&j.stage!=='Pronto'))return;ops.jobs.push({id:opId('OP'),orderId:id,stage:'Fila',printer:ops.printers.find(x=>x.status!=='Manutenção')?.name||'A definir',hours:6,assignee:'Pedro',priority:o.priority||'Normal',due:o.due||'2026-11-15'});setOrderOps(id,'Confirmado');auditOps('Ordem de produção criada',id)}
function payChargeOps(id){const c=ops.charges.find(x=>x.id===id);if(!c||c.status==='Pago')return;c.status='Pago';c.paidAt=OPS_DAY;const o=opOrder(c.orderId);if(o?.status==='Aguardando pagamento')setOrderOps(o.id,'Confirmado');const s=opSubscription(c.subscriptionId);if(s){if(s.status==='Pagamento pendente')s.status='Ativa';if(c.due>=s.nextRenewal)s.nextRenewal=opAddMonth(c.due);s.history.unshift({date:OPS_DAY,label:'Pagamento de '+money(c.amount)+' confirmado na simulação.'})}auditOps('Pagamento simulado confirmado',id)}
function clubItems(profile,finish='Marfim'){return (ops.settings.profiles[profile]||ops.settings.profiles['Cristã']).map(id=>{const p=products.find(x=>x.id===id)||products[0];return{id:p.id,name:p.name,img:p.img,price:p.price,qty:1,color:finish==='Surpresa'?p.colors[0]:finish,size:p.sizes[0]}})}
function generateClubCycle(s,result='Pendente'){const cycle=s.nextRenewal.slice(0,7);if(ops.charges.some(c=>c.subscriptionId===s.id&&c.cycle===cycle&&c.status!=='Cancelada'))return null;const oid=opId('PED'),cid=opId('COB'),paid=result==='Pago';ops.orders.unshift({id:oid,customerId:s.customerId,subscriptionId:s.id,type:'Clube',edition:opMonth(s.nextRenewal)+' · '+ops.settings.edition,profile:s.profile,items:clubItems(s.profile,s.finish),total:s.price,shipping:0,status:paid?'Confirmado':'Aguardando pagamento',created:OPS_DAY,due:s.nextRenewal.slice(0,8)+String(ops.settings.dispatchDay).padStart(2,'0'),address:{...s.address},chargeId:cid,tracking:'',carrier:'Correios (simulação)',priority:'Normal',notes:'Ciclo mensal de demonstração.'});ops.charges.unshift({id:cid,customerId:s.customerId,subscriptionId:s.id,orderId:oid,amount:s.price,method:s.payment,status:result,due:s.nextRenewal,paidAt:paid?OPS_DAY:null,description:'Clube · '+opMonth(s.nextRenewal),cycle});if(paid)s.nextRenewal=opAddMonth(s.nextRenewal);else if(result==='Recusado')s.status='Pagamento pendente';s.history.unshift({date:OPS_DAY,label:'Renovação simulada: '+result.toLowerCase()+'.'});auditOps('Ciclo mensal gerado: '+result,s.id);return oid}
function exportOpsCSV(name,headers,rows){const encode=v=>{let s=String(v??'');if(typeof v==='string'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(encode).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='amago-'+name+'-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
applyProductOps();syncStoreOps();

function nextClubShipment(s){const list=ops.orders.filter(o=>o.subscriptionId===s.id&&!['Enviado','Entregue','Cancelado'].includes(o.status)).sort((a,b)=>a.due.localeCompare(b.due));if(list.length)return opDate(list[0].due);if(['Pausada','Cancelada'].includes(s.status))return 'Sem novo envio';return opDate(s.nextRenewal.slice(0,8)+String(ops.settings.dispatchDay).padStart(2,'0'))}
function captureStoreTicket(d){let c=ops.clients.find(x=>x.email.toLowerCase()===d.email.toLowerCase());if(!c){c={id:opId('CLI'),name:d.name,email:d.email,status:'Ativo',created:OPS_DAY};ops.clients.unshift(c)}const id=opId('AT');ops.tickets.unshift({id,customerId:c.id,subject:d.topic,category:d.topic,status:'Aberto',priority:'Normal',assignee:'Camila',created:OPS_DAY,messages:[{by:'cliente',text:d.message,date:OPS_DAY}]});auditOps('Atendimento da loja aberto',id,'Cliente demo')}

function syncStorePayment(id){syncStoreOps();const o=ops.orders.find(o=>o.sourceOrderId===id);if(o){payChargeOps(o.chargeId);saveOps()}}
function storeShipmentContent(original){const o=ops.orders.find(x=>x.sourceOrderId===original.id);return o?shipmentCard(o):''}
function existingClubForEmail(email){const c=ops.clients.find(x=>x.email.toLowerCase()===email.toLowerCase());return c?ops.subscriptions.find(s=>s.customerId===c.id&&s.status!=='Cancelada'):null}
